    # Edges: 4 cliques of 3 (12 edges) + 3*3 = 9 inter-clique edges = 21 edges

    # We'll use backtracking with constraint propagation
    # Order: assign labels one vertex at a time

    n_vertices = 12
    n_edges = 21

    # Edge list: (u, v) where u, v are vertex indices 0-11
    # Vertex index = g*3 + i
    edges = []
    for g in range(4):
        edges.append((g*3+0, g*3+1))
        edges.append((g*3+1, g*3+2))
        edges.append((g*3+0, g*3+2))
    for g in range(3):
        for i in range(3):
            edges.append((g*3+i, (g+1)*3+i))

    # For each vertex, which edges does it participate in?
    vertex_edges = [[] for _ in range(n_vertices)]
    for idx, (u, v) in enumerate(edges):
        vertex_edges[u].append(idx)
        vertex_edges[v].append(idx)

    # Backtracking
    assignment = [-1] * n_vertices
    used_labels = set()
    edge_diffs = {}  # edge_idx -> diff

    def backtrack(v):
        if v == n_vertices:
            return True

        # Try each unused label
        for label in range(22):
            if label in used_labels:
                continue

            # Check if this label creates any duplicate edge differences
            conflict = False
            new_diffs = {}
            for eidx in vertex_edges[v]:
                u, w = edges[eidx]
                if assignment[u] != -1 and assignment[w] != -1:
                    d = abs(assignment[u] - assignment[w])
                    if d in edge_diffs.values() and eidx not in edge_diffs:
                        conflict = True
                        break
                    new_diffs[eidx] = d

            if conflict:
                continue

            # Check for duplicate among new diffs
            new_diff_values = list(new_diffs.values())
            if len(new_diff_values) != len(set(new_diff_values)):
                continue

            # Check new diffs don't conflict with existing
            ok = True
            for eidx, d in new_diffs.items():
                if eidx in edge_diffs:
                    if edge_diffs[eidx] != d:
                        ok = False
                        break
