                    for existing_eidx, existing_d in edge_diffs.items():
                        if existing_d == d:
                            ok = False
                            break
                if not ok:
                    break

            if not ok:
                continue

            # Assign
            assignment[v] = label
            used_labels.add(label)
            for eidx, d in new_diffs.items():
                edge_diffs[eidx] = d

            if backtrack(v + 1):
                return True

            # Undo
            assignment[v] = -1
            used_labels.remove(label)
            for eidx in new_diffs:
                del edge_diffs[eidx]

        return False

    if backtrack(0):
        print(f"Solution: {assignment}")
        return assignment
    else:
        print("UNSATISFIABLE")
